#include <cmath>
#include <cstdlib>

class Solution {
public:
    int minBishopMoves(int r1, int c1, int r2, int c2) {
        if ((r1 + c1) % 2 != (r2 + c2) % 2) return -1;
        if (r1 == r2 && c1 == c2) return 0;
        if (std::abs(r1 - r2) == std::abs(c1 - c2)) return 1;
        return 2;
    }
};

class Solution {
    public int minBishopMoves(int r1, int c1, int r2, int c2) {
        if ((r1 + c1) % 2 != (r2 + c2) % 2) return -1;
        if (r1 == r2 && c1 == c2) return 0;
        if (Math.abs(r1 - r2) == Math.abs(c1 - c2)) return 1;
        return 2;
    }
}

